async function compress(file,maxDim=700,q=.74,target=280000){if(!file.type.startsWith("image/"))throw new Error("Choose an image file.");const u=URL.createObjectURL(file);try{const im=await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>rej(new Error("Could not read image."));i.src=u;}),scale=Math.min(1,maxDim/Math.max(im.naturalWidth,im.naturalHeight)),w=Math.max(1,Math.round(im.naturalWidth*scale)),h=Math.max(1,Math.round(im.naturalHeight*scale)),c=document.createElement("canvas");c.width=w;c.height=h;c.getContext("2d").drawImage(im,0,0,w,h);let data=c.toDataURL("image/webp",q);while(data.length>target&&q>.36){q-=.07;data=c.toDataURL("image/webp",q);}if(data.length>700000)throw new Error("Image is still too large. Choose a smaller photo.");return data;}finally{URL.revokeObjectURL(u);}}
function preview(sel,src){const el=$(sel);if(!el)return;if(src)el.src=src;else el.removeAttribute("src");}
function busy(b,on,label){if(!b)return;b.disabled=on;if(on){b.dataset.oldLabel=b.textContent;b.textContent=label||"Saving…";}else b.textContent=b.dataset.oldLabel||label||"Save";}
function friendly(e){const c=e?.code||"",m=e?.message||"";if(c.includes("permission-denied"))return"Admin access is not permitted. Please sign in again.";if(c.includes("invalid-credential"))return"Email or password is incorrect.";if(c.includes("operation-not-allowed"))return"Email/Password sign-in is not enabled.";if(c.includes("resource-exhausted"))return"Firebase storage/quota limit was reached.";if(c.includes("unavailable")||c.includes("network")||m.toLowerCase().includes("network"))return"Internet connection is unstable. Please try again.";if(c.includes("not-found")||m.includes("No document to update"))return"This item was already deleted. The editor has been reset.";return m&&!m.includes("projects/")?m:"Something went wrong. Please try again.";}
function toast(text,type=""){const e=$("#globalToast");if(!e)return;e.textContent=text;e.className="global-toast "+type;e.hidden=false;clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>e.hidden=true,4200);}
