function ms(t){return t?.toMillis?t.toMillis():new Date(t||0).getTime()||0;}function stamp(x){return x.createdAt?.toMillis?x.createdAt.toMillis():x.updatedAt?.toMillis?x.updatedAt.toMillis():0;}
function albumTime(a){return a.date?.toMillis?a.date.toMillis():stamp(a);}function albumInputDate(a){const d=a?.date?.toDate?a.date.toDate():a?.date?new Date(a.date):null;return d&&!Number.isNaN(d.getTime())?d.toISOString().slice(0,10):"";}
function date(t){const d=t?.toDate?t.toDate():t?new Date(t):null;return d&&!Number.isNaN(d.getTime())?d.toLocaleString("en-MY",{day:"2-digit",month:"short",year:"numeric",hour:"numeric",minute:"2-digit"}):"TBA";}
function playerSort(a,b){return(a.number||"999").localeCompare(b.number||"999",undefined,{numeric:true})||(a.name||"").localeCompare(b.name||"");}
function slug(s){return String(s||"").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"item-"+Date.now();}
