function clean(v){if(v?.toDate)return v.toDate().toISOString();if(Array.isArray(v))return v.map(clean);if(v&&typeof v==="object"){const o={};Object.entries(v).forEach(a=>o[a[0]]=clean(a[1]));return o;}return v;}
